1	"use client";
2	
3	import { useEffect, useRef } from "react";
4	import Link from "next/link";
5	import { ArrowUpRight, Clock3 } from "lucide-react";
6	import Button from "@/components/ui/Button";
7	import { cn } from "@/components/ui/cn";
8	import { msSeitEingabe } from "./bausteine";
9	
10	/* ------------------------------------------------------------------
11	   Ergebnis → passende Anfrage. Steht am Ende jedes Rechner-Ergebnisses:
12	   die gerade berechnete Hauptzahl, ein Versprechen ohne Druck und EIN
13	   klarer nächster Schritt. Beim Klick wird die Anfrage vorbelegt
14	   (sessionStorage, gleiches Format wie formular/Entwurf) – Nachricht mit
15	   den Eingaben und dem Teilen-Link. Ohne JS bleibt es ein normaler Link.
16	   ------------------------------------------------------------------ */
17	
18	const PRAEFIX = "ov-entwurf:";
19	const MARKE = "Aus dem "; // eigene Vorbelegungen erkennen: überschreiben ja, Nutzertext nie
20	
21	/** Nachricht der Anfrage `anfrage-<typ>` vorbelegen (nur leer oder eigene frühere Vorbelegung). */
22	export function anfrageVorbelegen(typ, nachricht) {
23	  if (!typ || !nachricht) return;
24	  try {
25	    const schluessel = `${PRAEFIX}anfrage-${typ}`;
26	    const alt = JSON.parse(window.sessionStorage.getItem(schluessel) || "null")?.werte || {};
27	    if (alt.nachricht && !String(alt.nachricht).startsWith(MARKE)) return;
28	    const text = `${nachricht}\n\nMeine Eingaben: ${window.location.href}`.slice(0, 4800);
29	    window.sessionStorage.setItem(schluessel, JSON.stringify({ werte: { ...alt, nachricht: text }, zeit: Date.now() }));
30	  } catch {
31	    /* Speicher gesperrt (privater Modus) – der Link funktioniert trotzdem */
32	  }
33	}
34	
35	const bewegungReduziert = () => typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
36	
37	/**
38	 * typ        Anfrage-Typ (/kontakt?anliegen=<typ> bzw. Formular am Ziel), bestimmt den Entwurfsschlüssel
39	 * href       Ziel der Anfrage (crawlbarer Link)
40	 * kennzahl   die gerade berechnete Hauptzahl (ReactNode, z. B. <Zahl …/>)
41	 * satz       Text nach der Zahl, z. B. „Projekt-IRR – mit Ihren Projektdaten nachrechnen lassen“
42	 * nachricht  Text für die vorbelegte Anfrage (beginnt mit „Aus dem …“)
43	 * signal     Wert, dessen Änderung nach einer Eingabe die Karte kurz aufleuchten lässt
44	 * sekundaer  [{ href, label }] – leise Textlinks, kein zweiter lauter Knopf
45	 */
46	export default function ErgebnisAnfrage({
47	  typ,
48	  href,
49	  eyebrow = "Mit diesem Ergebnis weiter",
50	  kennzahl,
51	  satz,
52	  nachricht,
53	  label = "Mit diesem Ergebnis anfragen",
54	  versprechen = "Wir melden uns in der Regel innerhalb von zwei Werktagen – kostenlos und unverbindlich.",
55	  signal,
56	  sekundaer = [],
57	  hinweis,
58	  className,
59	}) {
60	  const leuchten = useRef(null);
61	  const zuletzt = useRef(-1e9);
62	  const erst = useRef(true);
63	
64	  // Feedback: Ergebnis hat sich durch eine Eingabe verändert → Karte leuchtet einmal leise auf
65	  // (nur opacity, höchstens alle 6 s, nur wenn die Karte im Bild ist, nie beim Laden).
66	  useEffect(() => {
67	    if (erst.current) {
68	      erst.current = false;
69	      return undefined;
70	    }
71	    if (msSeitEingabe() > 800 || bewegungReduziert()) return undefined;
72	    const t = setTimeout(() => {
73	      const el = leuchten.current;
74	      if (!el || typeof el.animate !== "function") return;
75	      const jetzt = performance.now();
76	      if (jetzt - zuletzt.current < 6000) return;
77	      const box = el.getBoundingClientRect();
78	      if (box.bottom < 60 || box.top > window.innerHeight - 60) return;
79	      zuletzt.current = jetzt;
80	      el.animate([{ opacity: 0 }, { opacity: 1, offset: 0.35 }, { opacity: 0 }], { duration: 1200, easing: "cubic-bezier(.2,.8,.2,1)" });
81	    }, 650);
82	    return () => clearTimeout(t);
83	  }, [signal]);
84	
85	  return (
86	    <div className={cn("mt-7 border-t border-ink-100 pt-6", className)}>
87	      <div data-ergebnis-anfrage="" className="relative isolate overflow-hidden rounded-3xl bg-ov-50 p-5 ring-1 ring-ov-200 print:hidden md:p-6">
88	        {/* Aufleuchten (aria-hidden, lässt Klicks durch) */}
89	        <span
90	          ref={leuchten}
91	          aria-hidden="true"
92	          className="pointer-events-none absolute inset-0 -z-10 rounded-3xl opacity-0 ring-2 ring-inset ring-ov-400"
93	          style={{ background: "radial-gradient(120% 140% at 0% 0%, rgba(174,208,131,0.45), transparent 60%)" }}
94	        />
95	        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
96	          <div className="min-w-0">
97	            <p className="text-[13px] font-semibold text-ov-800">{eyebrow}</p>
98	            <p className="mt-1 font-display text-[19px] font-bold leading-snug text-ink-900">
99	              {kennzahl != null && (
100	                <>
101	                  ≈ <span className="ov-num whitespace-nowrap">{kennzahl}</span>{" "}
102	                </>
103	              )}
104	              {satz}
105	            </p>
106	            <p className="mt-1.5 flex items-start gap-1.5 text-[13px] leading-snug text-ink-600">
107	              <Clock3 aria-hidden="true" className="mt-0.5 h-3.5 w-3.5 shrink-0 text-ov-600" />
108	              {versprechen}
109	            </p>
110	          </div>
111	          <Button href={href} size="lg" pfeil className="w-full shrink-0 sm:w-auto" data-ov-cta onClick={() => anfrageVorbelegen(typ, nachricht)}>
112	            {label}
113	          </Button>
114	        </div>
115	        {sekundaer.length > 0 && (
116	          <ul className="mt-4 flex flex-wrap gap-x-5 gap-y-1 border-t border-ov-200/70 pt-3">
117	            {sekundaer.map((s) => (
118	              <li key={s.href}>
119	                <Link
120	                  href={s.href}
121	                  className="group inline-flex min-h-10 items-center gap-1 rounded-lg text-[14px] font-semibold text-ov-800 underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500"
122	                >
123	                  {s.label}
124	                  <ArrowUpRight aria-hidden="true" className="ov-pfeil h-4 w-4" />
125	                </Link>
126	              </li>
127	            ))}
128	          </ul>
129	        )}
130	      </div>
131	      {hinweis && <p className="mt-4 text-[13px] leading-relaxed text-ink-500">{hinweis}</p>}
132	    </div>
133	  );
134	}
