// src/lib/plattform/matching.js
//
// Passung Projekt ↔ Suchprofil eines Investors (0–100 Punkte).
// Gewichte: Typ 25, Phase 25, Land 20, Größe 20, Ticket 10.
// Leere Kriterien im Profil zählen als „egal“ (volle Punkte).

import { preisGesamt } from "./format";
import { PHASEN } from "@/lib/invest/markt";
import { LAENDER, PROJEKT_TYPEN } from "./konstanten";

export function matching(projekt, profil) {
  if (!projekt) return { score: 0, gruende: [] };
  const p = profil || {};
  const gruende = [];
  let score = 0;

  // Typ
  if (!p.typen?.length || p.typen.includes(projekt.typ)) {
    score += 25;
    if (p.typen?.length) gruende.push(PROJEKT_TYPEN[projekt.typ] || projekt.typ);
  }

  // Phase – benachbarte Phase gibt halbe Punkte
  if (!p.phasen?.length) score += 25;
  else if (p.phasen.includes(projekt.phase)) {
    score += 25;
    gruende.push(PHASEN.find((x) => x.id === projekt.phase)?.kurz || projekt.phase);
  } else {
    const idx = PHASEN.findIndex((x) => x.id === projekt.phase);
    const nah = idx >= 0 && p.phasen.some((ph) => Math.abs(PHASEN.findIndex((x) => x.id === ph) - idx) === 1); // Projekt ohne/mit unbekannter Phase: nicht „benachbart“
    if (nah) score += 12;
  }

  // Land
  if (!p.laender?.length || p.laender.includes(projekt.land)) {
    score += 20;
    if (p.laender?.length) gruende.push(LAENDER[projekt.land] || projekt.land);
  }

  // Größe – bis 25 % außerhalb der Spanne halbe Punkte
  const m = Number(projekt.mwp) || 0;
  const min = Number(p.mwpMin) || 0;
  const max = Number(p.mwpMax) || Infinity;
  if (m >= min && m <= max) {
    score += 20;
    if (p.mwpMin || p.mwpMax) gruende.push("Größe passt");
  } else if (m >= min * 0.75 && m <= max * 1.25) score += 10;

  // Ticket
  const preis = preisGesamt(projekt);
  const tMin = Number(p.ticketMin) || 0;
  const tMax = Number(p.ticketMax) || Infinity;
  if (!p.ticketMin && !p.ticketMax) score += 10;
  else if (preis === null) score += 5; // auf Anfrage – offen
  else if (preis >= tMin && preis <= tMax) {
    score += 10;
    gruende.push("Ticket passt");
  }

  return { score: Math.round(score), gruende };
}
// src/lib/plattform/hashkette.js
//
// Revisionssicheres Aktivitätsprotokoll: Hash-Kette über alle Einträge.
//
//   hash_n = SHA-256( prevHash_n + "\n" + inhalt_n )      mit prevHash_n = hash_(n-1)
//
// `inhalt` ist eine kanonische JSON-Darstellung der fachlichen Felder in fester Reihenfolge
// (id, am, nutzerId, aktion, objektArt, objektId, text, ip). Wer einen Eintrag nachträglich ändert,
// löscht, einfügt oder umsortiert, bricht die Kette ab dieser Stelle – verifyChain() meldet die
// erste Abweichung. Identisches Verfahren in Frappe: plattform/hashkette.py (Feld prev_hash/entry_hash).
//
// Werden alte Einträge archiviert (Demo: > 5000 Einträge), bleibt ein Anker { hash, anzahl, bis }
// stehen: die Prüfung beginnt dann beim Anker-Hash statt beim Startwert.
//
// Nur serverseitig (node:crypto).

import { createHash } from "node:crypto";

export const KETTE_START = "0".repeat(64);
export const KETTE_FELDER = ["id", "am", "nutzerId", "aktion", "objektArt", "objektId", "text", "ip"];

const wert = (v) => (v === undefined || v === null ? "" : String(v));

/** Kanonischer Inhalt eines Eintrags (unabhängig von zusätzlichen Feldern wie `nutzer`) */
export function eintragInhalt(e) {
  return JSON.stringify(KETTE_FELDER.map((k) => [k, wert(e?.[k])]));
}

export function eintragHash(prevHash, e) {
  return createHash("sha256").update(`${prevHash}\n${eintragInhalt(e)}`, "utf8").digest("hex");
}

/** Eintrag an die Kette anhängen: setzt prevHash und hash (verändert das Objekt) */
export function verketten(e, prevHash = KETTE_START) {
  e.prevHash = prevHash || KETTE_START;
  e.hash = eintragHash(e.prevHash, e);
  return e;
}

/**
 * Kette prüfen. `eintraege` in Einfügereihenfolge (älteste zuerst).
 * Liefert { ok, geprueft, fehler: [{ index, id, grund }], letzterHash, start }.
 * Mit `alleFehler: false` (Standard) endet die Prüfung beim ersten Bruch.
 */
export function verifyChain(eintraege = [], { anker = null, alleFehler = false } = {}) {
  const start = anker?.hash || KETTE_START;
  let prev = start;
  const fehler = [];
  let geprueft = 0;
  for (let i = 0; i < eintraege.length; i++) {
    const e = eintraege[i];
    geprueft++;
    let grund = "";
    if (!e?.hash) grund = "Eintrag ohne Hash (ungesichert eingefügt)";
    else if (e.prevHash !== prev) grund = "Verweis auf den Vorgänger passt nicht (Eintrag gelöscht, eingefügt oder umsortiert)";
    else if (eintragHash(prev, e) !== e.hash) grund = "Inhalt wurde nachträglich verändert";
    if (grund) {
      fehler.push({ index: i, id: e?.id || null, am: e?.am || null, grund });
      if (!alleFehler) break;
    }
    prev = e?.hash || prev;
  }
  return { ok: fehler.length === 0, geprueft, anzahl: eintraege.length, fehler, letzterHash: prev, start };
}

/** Python-Name wie in Frappe (plattform/hashkette.py) */
export const verify_chain = verifyChain;
// src/lib/plattform/server/pdf.js
//
// Kleiner PDF-Erzeuger ohne Fremdpakete: mehrere Seiten (A4), Standardschriften Helvetica und
// Helvetica-Bold (WinAnsi/CP1252, also mit Umlauten, ß, €, „“ – –), Flächen, Linien, Farben,
// Textbreiten nach den Adobe-Metriken (für sauberen Zeilenumbruch). Koordinaten: Punkte, Ursprung
// OBEN links (wird intern umgerechnet), y beim Text = Grundlinie.
//
// Nur serverseitig (Buffer). Genutzt für Exposé-PDFs und die Demo-Dokumente.

export const A4 = { breite: 595.28, hoehe: 841.89 };

// Zeichenbreiten (1/1000 em) für die Zeichen 32–126
const W_REG = [
  278, 278, 355, 556, 556, 889, 667, 191, 333, 333, 389, 584, 278, 333, 278, 278, 556, 556, 556, 556, 556, 556, 556, 556, 556, 556, 278, 278, 584, 584, 584, 556,
  1015, 667, 667, 722, 722, 667, 611, 778, 722, 278, 500, 667, 556, 833, 722, 778, 667, 778, 722, 667, 611, 722, 667, 944, 667, 667, 611, 278, 278, 278, 469, 556,
  333, 556, 556, 500, 556, 556, 278, 556, 556, 222, 222, 500, 222, 833, 556, 556, 556, 556, 333, 500, 278, 556, 500, 722, 500, 500, 500, 334, 260, 334, 584,
];
const W_BOLD = [
  278, 333, 474, 556, 556, 889, 722, 238, 333, 333, 389, 584, 278, 333, 278, 278, 556, 556, 556, 556, 556, 556, 556, 556, 556, 556, 333, 333, 584, 584, 584, 611,
  975, 722, 722, 722, 722, 667, 611, 778, 722, 278, 556, 722, 611, 833, 722, 778, 667, 778, 722, 667, 611, 722, 667, 944, 667, 667, 611, 333, 278, 333, 584, 556,
  333, 556, 611, 556, 611, 556, 333, 611, 611, 278, 278, 556, 278, 889, 611, 611, 611, 611, 389, 556, 333, 611, 556, 778, 556, 556, 500, 389, 280, 389, 584,
];
// Sonderzeichen: [Breite normal, Breite fett, CP1252-Code]
const SONDER = {
  "€": [556, 556, 0x80], "‚": [222, 278, 0x82], "„": [333, 500, 0x84], "…": [1000, 1000, 0x85], "‰": [1000, 1000, 0x89],
  "‘": [222, 278, 0x91], "’": [222, 278, 0x92], "“": [333, 500, 0x93], "”": [333, 500, 0x94], "•": [350, 350, 0x95],
  "–": [556, 556, 0x96], "—": [1000, 1000, 0x97], "™": [1000, 1000, 0x99], "ß": [611, 611, 0xdf], "·": [278, 278, 0xb7],
  "°": [400, 400, 0xb0], "²": [333, 333, 0xb2], "³": [333, 333, 0xb3], "×": [584, 584, 0xd7], "«": [556, 556, 0xab],
  "»": [556, 556, 0xbb], "§": [556, 556, 0xa7], "©": [737, 737, 0xa9], "®": [737, 737, 0xae], "±": [584, 584, 0xb1],
};
const ERSATZ = [
  [/[    ]/g, " "], [/≥/g, ">="], [/≤/g, "<="], [/→/g, "->"], [/≈/g, "ca. "], [/[‐‑]/g, "-"],
  [/[​-‍﻿]/g, ""], [/\t/g, " "],
];

/** Text für die Ausgabe vereinheitlichen (Zeichen außerhalb von CP1252 ersetzen) */
export function normalisieren(s) {
  let t = String(s ?? "");
  for (const [re, x] of ERSATZ) t = t.replace(re, x);
  return t;
}

function zeichen(c) {
  const code = c.charCodeAt(0);
  if (code >= 32 && code <= 126) return { code, basis: c };
  if (SONDER[c]) return { code: SONDER[c][2], sonder: SONDER[c] };
  if (code >= 0xa0 && code <= 0xff) {
    const basis = c.normalize("NFD")[0];
    return { code, basis: basis.charCodeAt(0) >= 32 && basis.charCodeAt(0) <= 126 ? basis : "o" };
  }
  return { code: 63, basis: "?" };
}

/** Breite eines Texts in Punkten */
export function textBreite(text, groesse = 10, fett = false) {
  let summe = 0;
  for (const c of normalisieren(text)) {
    const z = zeichen(c);
    if (z.sonder) summe += z.sonder[fett ? 1 : 0];
    else summe += (fett ? W_BOLD : W_REG)[z.basis.charCodeAt(0) - 32] ?? 556;
  }
  return (summe * groesse) / 1000;
}

/** Zeilenumbruch nach Breite (Wörter; überlange Wörter werden hart getrennt) */
export function umbrechen(text, maxBreite, groesse = 10, fett = false) {
  const zeilen = [];
  for (const absatz of normalisieren(text).split(/\n/)) {
    const woerter = absatz.split(/ +/).filter((w, i, a) => w || a.length === 1);
    let zeile = "";
    for (let wort of woerter) {
      while (textBreite(wort, groesse, fett) > maxBreite && wort.length > 1) {
        // überlanges Wort (z. B. URL) zerlegen
        let n = wort.length - 1;
        while (n > 1 && textBreite(wort.slice(0, n), groesse, fett) > maxBreite) n--;
        if (zeile) {
          zeilen.push(zeile);
          zeile = "";
        }
        zeilen.push(wort.slice(0, n));

// src/lib/plattform/dealroom.js
//
// Stammlisten und reine Regeln des Deal-Rooms (Q&A, Bieterverfahren, Datenraum 2.0,
// Investor-Pipeline, Anbieter-Cockpit). Client- und serverseitig nutzbar – keine Node-Importe.
// Frappe spiegelt die Tabellen in `plattform/dealroom_regeln.py` (identisch halten).
//
// Grundsatz Umgehungsschutz: Anbieter und Investoren sehen sich gegenseitig NICHT, bis das
// Backoffice die Kontakte je Interesse freigibt („Kontaktfreigabe“). Bis dahin erscheinen
// Investoren beim Anbieter nur als Pseudonym („Investor A“), der Anbieter beim Investor nur
// als „Anbieter“. Freitexte (Fragen, Antworten, Gebotsbedingungen) werden zusätzlich von
// E-Mail-Adressen, Telefonnummern und Links bereinigt.

import { DATENRAUM_STATUS } from "./prozesse";

// ---------------------------------------------------------------- Q&A

export const QA_KATEGORIEN = {
  technisch: "Technisch",
  rechtlich: "Rechtlich",
  kaufmaennisch: "Kaufmännisch",
  netz: "Netz",
};
export const QA_KATEGORIE_IDS = Object.keys(QA_KATEGORIEN);

/**
 * Status einer Frage (intern). Für Investoren zählt nur offen/beantwortet (`qaOeffentlicherStatus`).
 *   eingereicht     – Investor hat gefragt, Moderation durch ÖkoInvest ausstehend
 *   freigegeben     – anonymisiert an den Anbieter weitergegeben, Antwortfrist läuft
 *   beantwortet     – Anbieter hat geantwortet, Freigabe der Antwort durch ÖkoInvest ausstehend
 *   veroeffentlicht – Antwort freigegeben (für den Fragenden, optional für alle NDA-Investoren)
 *   abgelehnt       – nicht zugelassen (z. B. Umgehungsversuch, Dublette)
 */
export const FRAGE_STATUS = {
  eingereicht: { label: "In Moderation", ton: "warn" },
  freigegeben: { label: "Offen beim Anbieter", ton: "info" },
  beantwortet: { label: "Antwort in Prüfung", ton: "warn" },
  veroeffentlicht: { label: "Beantwortet", ton: "ok" },
  abgelehnt: { label: "Nicht zugelassen", ton: "neutral" },
};
export const qaOeffentlicherStatus = (s) => (s === "veroeffentlicht" ? "beantwortet" : s === "abgelehnt" ? "abgelehnt" : "offen");
export const QA_FRIST_TAGE = { standard: 5, min: 1, max: 30 };

// ---------------------------------------------------------------- Datenraum 2.0

/** Standard-Index des Datenraums (Reihenfolge = Nummerierung) */
export const DATENRAUM_ORDNER = [
  { id: "flaeche", nr: "01", label: "Fläche & Sicherung", text: "Lageplan, Grundbuch, Pacht- und Nutzungsverträge" },
  { id: "planung", nr: "02", label: "Planung & Genehmigung", text: "Aufstellungs-/Satzungsbeschluss, Widmung, Baugenehmigung, Gutachten" },
  { id: "netz", nr: "03", label: "Netz", text: "Netzanfrage, Netzanschlusszusage, Reservierung, Trassenplanung" },
  { id: "technik", nr: "04", label: "Technik", text: "Anlagenlayout, Komponenten, Betriebsdaten, Wartung" },
  { id: "ertrag", nr: "05", label: "Ertrag", text: "Ertragsgutachten (P50/P90), Verschattung, Messdaten" },
  { id: "vertraege", nr: "06", label: "Verträge", text: "EEG-/EAG-Zuschlag, PPA, Direktvermarktung, Dienstleister" },
  { id: "finanzen", nr: "07", label: "Finanzen", text: "Finanzmodell, Kostenschätzung, Steuern, Förderungen" },
  { id: "allgemein", nr: "00", label: "Allgemein", text: "Exposé, Steckbrief, Sonstiges" },
];
export const DATENRAUM_ORDNER_IDS = DATENRAUM_ORDNER.map((o) => o.id);
export const ordnerLabel = (id) => DATENRAUM_ORDNER.find((o) => o.id === id)?.label || "Allgemein";

/** Ordner aus dem Checklisten-Schlüssel eines Dokuments (Vorbelegung) */
export const ORDNER_FUER_CHECKLISTE = {
  pacht: "flaeche",
  lageplan: "flaeche",
  netzzusage: "netz",
  aufstellung: "planung",
  gutachten: "planung",
  satzung: "planung",
  baugenehmigung: "planung",
  ertrag: "ertrag",
  eeg: "vertraege",
  betrieb: "technik",
};

export function ordnerVorschlag(dokument) {
  if (ORDNER_FUER_CHECKLISTE[dokument?.checkliste]) return ORDNER_FUER_CHECKLISTE[dokument.checkliste];
  const n = String(dokument?.name || "").toLowerCase();
  if (/netz|einspeis|umspann/.test(n)) return "netz";
  if (/ertrag|p50|p90|yield/.test(n)) return "ertrag";
  if (/finanz|kosten|capex|modell|steuer/.test(n)) return "finanzen";
  if (/vertrag|ppa|eeg|eag|zuschlag|direktvermarkt/.test(n)) return "vertraege";
  if (/beschluss|satzung|genehmig|bewilligung|widmung|gutacht|b-plan|bebauungsplan/.test(n)) return "planung";
  if (/lageplan|grundbuch|flur|pacht|nutzungsvertr/.test(n)) return "flaeche";
  if (/layout|modul|wechselricht|technik|betrieb|wartung/.test(n)) return "technik";
  return "allgemein";
}

/**
 * Freigabestufen. Stufe 1: nach NDA-Freigabe (Datenraum frei). Stufe 2: nach LOI bzw. als
 * zugelassener Teilnehmer der verbindlichen Runde eines Bieterverfahrens.
 */
export const DATENRAUM_STUFEN = {
  1: { label: "Stufe 1", text: "nach NDA-Freigabe" },
  2: { label: "Stufe 2", text: "nach LOI bzw. Zulassung zur verbindlichen Runde" },
};
export const STUFE2_STATUS = ["loi_abgegeben", "loi_angenommen", "abgeschlossen"];

/** Höchste Stufe eines Investors (0 = kein Datenraum) */
export function investorStufe(interesse, { verbindlichZugelassen = false } = {}) {
  if (!interesse || !DATENRAUM_STATUS.includes(interesse.status)) return 0;
  if (STUFE2_STATUS.includes(interesse.status) || verbindlichZugelassen) return 2;
  return 1;
}

/** Download-Dateiname mit „Wasserzeichen“ (Empfänger + Datum) – ASCII-sicher, Endung bleibt */
export function wasserzeichenName(name, empfaenger, am = new Date()) {
  const s = String(name || "dokument.pdf");
  const punkt = s.lastIndexOf(".");
  const basis = (punkt > 0 ? s.slice(0, punkt) : s).trim();
  const endung = punkt > 0 ? s.slice(punkt) : "";
  const wer = [empfaenger?.vorname, empfaenger?.nachname].filter(Boolean).join(" ").replace(/\s*\(demo\)\s*/i, " Demo").trim() || "Empfaenger";
  const tag = new Date(am).toLocaleDateString("sv-SE", { timeZone: "Europe/Vienna" });
  const sauber = (x) => x.replace(/[\\/:*?"<>|]+/g, "_").replace(/\s+/g, " ").trim();
  return `${sauber(basis)} - vertraulich fuer ${sauber(wer)} ${tag}${endung}`.slice(0, 180);
}

// ---------------------------------------------------------------- Umgehungsschutz

const MUSTER = [
  /[A-Z0-9._%+-]{1,64}@[A-Z0-9.-]{1,120}\.[A-Z]{2,24}/gi, // E-Mail
  /\b(?:https?:\/\/|www\.)\S+/gi, // Links
  /(?:\+|00)\d[\d ()/.-]{6,20}\d/g, // internationale Rufnummer
  /\b0\d{2,5}(?:[ /.-]?\d){4,14}\b/g, // nationale Rufnummer
];

/** Kontaktdaten aus Freitext entfernen. Liefert { text, bereinigt } */
export function anonymisieren(text) {
  let t = String(text ?? "");
  let bereinigt = false;
  for (const m of MUSTER) {
    t = t.replace(m, () => {
      bereinigt = true;
      return "[Kontaktangabe entfernt]";
    });
  }
  return { text: t, bereinigt };
}

/** Pseudonym je Reihenfolge: 0 → „A“, 25 → „Z“, 26 → „AA“ */
export function pseudonymBuchstabe(i) {
  let n = Math.max(0, i | 0);
  let s = "";
  do {
    s = String.fromCharCode(65 + (n % 26)) + s;
    n = Math.floor(n / 26) - 1;
  } while (n >= 0);
  return s;
}

